import media from "./media.json";

/**
 * Shapes the page copy is written in. Every picture names a capture in
 * `media.json` (generated by the capture pipeline; see web/DESIGN.md), so a
 * page cannot point at a picture that does not exist: an unknown key fails
 * the type check and the build.
 */

export type MediaKey = keyof typeof media;

export interface Picture {
  k: MediaKey;
  alt: string;
}

/** A point with a bold lead and the rest of the sentence. */
export type Point = [lead: string, rest: string];

export interface Card {
  title: string;
  body: string;
  pic: Picture;
  /** Grid width out of six columns on wide screens. */
  w?: 2 | 3 | 4 | 6;
  /** Inset the picture on all sides instead of bleeding it off the bottom edge. */
  inset?: boolean;
}

export interface Faq {
  q: string;
  a: string;
}

export interface SplitBlock {
  eyebrow: string;
  title: string;
  body: string;
  points: Point[];
  pic: Picture;
  flip?: boolean;
}

export interface BentoBlock {
  eyebrow: string;
  title: string;
  body: string;
  cards: Card[];
}

/** Pixel size and capture density (2 for the main window at device scale 2, 1 otherwise). */
export function mediaSize(k: MediaKey): { w: number; h: number; x: number } {
  const entry: { w: number; h: number; x?: number } = media[k];
  return { w: entry.w, h: entry.h, x: entry.x ?? 1 };
}
